import numpy as np
import time


def compute_R(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    num = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    den = s * s * np.max(L)
    if den <= 0:
        return -1.0
    return num / den


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 3.0)

    # Baseline from `start` (or a reasonable default).
    if start is not None:
        best = np.asarray(start, dtype=float).ravel().copy()
        if best.size == 0 or not np.all(np.isfinite(best)) or np.any(best < 0):
            best = np.ones(50)
    else:
        best = np.ones(50)

    best_R = compute_R(best)
    rng = np.random.default_rng(12345)

    # The constant function has R = 2/3. A smooth bump (e.g. Gaussian-like)
    # makes the autoconvolution flatter, which raises R. Try a few shapes.
    def try_candidate(h):
        nonlocal best, best_R
        h = np.asarray(h, dtype=float)
        if h.size == 0 or h.size > 50000:
            return
        if not np.all(np.isfinite(h)) or np.any(h < 0) or h.sum() <= 0:
            return
        r = compute_R(h)
        if r > best_R:
            best_R = r
            best = h.copy()

    # Candidate families: raised-cosine bumps of various widths, on various N.
    for N in (20, 40, 50, 80, 100, 150, 200, 300, 400, 500, 700, 1000):
        x = np.linspace(-1.0, 1.0, N)
        for p in (1, 2, 3, 4, 6, 8, 12, 20):
            w = np.maximum(0.0, 1.0 - np.abs(x) ** p)
            try_candidate(w)
        for sigma in (0.15, 0.2, 0.3, 0.4, 0.5, 0.7, 1.0):
            try_candidate(np.exp(-0.5 * (x / sigma) ** 2))
        # triangle / parabolic
        try_candidate(np.maximum(0.0, 1.0 - np.abs(x)))
        try_candidate(np.maximum(0.0, 1.0 - x * x))

    # Local refinement: coordinate-wise multiplicative perturbations.
    if best.size <= 50000:
        step = 0.15
        while time.process_time() < deadline:
            improved = False
            n = best.size
            # Random subset of coordinates per sweep.
            order = rng.permutation(n)
            for idx in order:
                if time.process_time() >= deadline:
                    break
                base = best[idx]
                for fac in (1.0 + step, 1.0 - step, 1.0 + 2 * step, 1.0 - 2 * step):
                    if base * fac < 0:
                        continue
                    cand = best.copy()
                    cand[idx] = base * fac
                    r = compute_R(cand)
                    if r > best_R:
                        best = cand
                        best_R = r
                        improved = True
                        break
            if not improved:
                step *= 0.6
                if step < 1e-4:
                    break
        # Re-try with additive small perturbations to escape flat spots.
        if time.process_time() < deadline:
            scale = 0.05 * (best.max() if best.max() > 0 else 1.0)
            for _ in range(200):
                if time.process_time() >= deadline:
                    break
                cand = best + rng.normal(0.0, scale, size=best.size)
                cand = np.maximum(cand, 0.0)
                try_candidate(cand)

    return best

