def _R(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a*a + a*b + b*b) / 3.0
    linf = L.max()
    if linf <= 0:
        return -1.0
    return l2sq / (s*s*linf)

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_R = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and np.any(s > 0) and np.all(s >= 0):
            r = _R(s)
            if r > best_R:
                best_R = r; best = s.copy()

    # Smooth bump: (1-|x|^p)^q family; R maximized by flat-topped autoconvolution.
    # Autoconvolution of a rectangle is triangular; of a smoother bump is flatter.
    # Try a family of shapes on moderate N.
    def try_(h):
        nonlocal best, best_R
        h = np.asarray(h, dtype=float)
        if h.size == 0 or h.size > 50000 or np.any(h < 0) or h.sum() <= 0:
            return False
        if not np.all(np.isfinite(h)):
            return False
        r = _R(h)
        if r > best_R:
            best_R = r; best = h.copy(); return True
        return False

    # scan smooth shapes
    for N in (40, 80, 120, 200, 300, 500, 800, 1200):
        if time.process_time() > deadline: break
        x = np.linspace(-1.0, 1.0, N)
        ax = np.abs(x)
        for p in (1.5, 2, 3, 4, 6, 8, 12, 20, 40):
            for q in (0.5, 1, 2, 4):
                w = np.maximum(0.0, 1.0 - ax**p)**q
                try_(w)
        for sig in (0.2, 0.3, 0.5, 0.7, 1.0):
            try_(np.exp(-0.5*(x/sig)**2))
        # cosine bump
        try_(np.cos(0.5*np.pi*x)**2)
        try_(np.maximum(0.0, np.cos(0.5*np.pi*x)))

    if best is None:
        best = np.ones(50); best_R = _R(best)

    rng = np.random.default_rng(7)
    n = best.size
    # Coordinate refinement with multiplicative + additive perturbations, batched.
    step = 0.2
    scale = best.max() if best.max() > 0 else 1.0
    while time.process_time() < deadline:
        improved = False
        order = rng.permutation(n)
        for idx in order:
            if time.process_time() >= deadline: break
            base = best[idx]
            for fac in (1.0+step, 1.0-step, 1.0+2*step, 1.0-2*step):
                if base*fac < 0: continue
                cand = best.copy(); cand[idx] = base*fac
                if try_(cand):
                    improved = True; break
            if not improved:
                for d in (step*scale, -step*scale, 2*step*scale, -2*step*scale):
                    v = base + d
                    if v < 0: v = 0.0
                    cand = best.copy(); cand[idx] = v
                    if try_(cand):
                        improved = True; break
        if not improved:
            step *= 0.6
            if step < 1e-4:
                # global random restarts around best
                for _ in range(50):
                    if time.process_time() >= deadline: break
                    cand = np.maximum(best + rng.normal(0, 0.1*scale, n), 0)
                    try_(cand)
                step = 0.1

    return best

