import numpy as np
import time


def _R_full(h):
    """Return (R, L, linf) using exact knot formula."""
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return -1.0, None, 0.0
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[1:-1] = c
    L[-1] = 0.0
    a = L[:-1]
    b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    linf = L.max()
    if linf <= 0:
        return -1.0, L, 0.0
    return l2sq / (s * s * linf), L, linf


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 2.5)

    best = None
    best_R = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and np.all(s >= 0) and s.sum() > 0:
            r, _, _ = _R_full(s)
            if r > best_R:
                best_R = r
                best = s.copy()

    def make_bump(N, p):
        x = np.linspace(-1.0, 1.0, N)
        return np.maximum(0.0, 1.0 - np.abs(x) ** p)

    if best is None:
        for N in (200, 400, 800, 1600, 3000):
            if time.process_time() > deadline:
                break
            for p in (1.5, 2, 3, 4, 6, 8, 12, 20):
                h = make_bump(N, p)
                r, _, _ = _R_full(h)
                if r > best_R:
                    best_R = r
                    best = h
        if best is None:
            best = make_bump(400, 4)
            best_R, _, _ = _R_full(best)

    best = np.asarray(best, dtype=float).copy()

    rng = np.random.default_rng(20240501)

    # --- Fast incremental local search ---
    # Key speedup: when h[idx] changes by delta, autoconvolution changes by
    # delta * (shifted h + h shifted). Update L incrementally instead of full convolve.
    def local_search(h, R, iters, step0, deadline, rng):
        n = h.size
        step = step0
        # Precompute full L once
        _, L, linf = _R_full(h)
        s = h.sum()
        # We'll recompute R cheaply from L when needed, but incremental L update is
        # complex; instead use coordinate descent with fast full recompute but
        # fewer evals by doing batch/analytic direction.
        for _ in range(iters):
            if time.process_time() > deadline:
                break
            improved = False
            order = rng.permutation(n)
            for idx in order:
                if time.process_time() > deadline:
                    break
                base = h[idx]
                best_local = R
                best_val = base
                for fac in (1.0 + step, 1.0 - step, 1.0 + 2 * step, 1.0 - 2 * step):
                    v = base * fac
                    if v < 0:
                        continue
                    h[idx] = v
                    r, _, _ = _R_full(h)
                    if r > best_local:
                        best_local = r
                        best_val = v
                h[idx] = best_val
                if best_local > R:
                    R = best_local
                    improved = True
            if not improved:
                step *= 0.6
                if step < 1e-5:
                    break
        return h, R

    # Multi-resolution refinement
    sizes = []
    if best.size not in (200, 400, 800, 1600, 3200):
        sizes.append(best.size)
    for target in (200, 400, 800, 1600, 3200):
        if target != best.size:
            sizes.append(target)
    if best.size > 3200:
        sizes = [best.size]

    for N in sizes:
        if time.process_time() > deadline:
            break
        if best.size != N:
            xs = np.linspace(0.0, 1.0, best.size)
            xd = np.linspace(0.0, 1.0, N)
            h = np.interp(xd, xs, best)
        else:
            h = best.copy()
        h = np.maximum(h, 0.0)
        R, _, _ = _R_full(h)
        h, R = local_search(h, R, iters=4, step0=0.2, deadline=deadline, rng=rng)
        h, R = local_search(h, R, iters=4, step0=0.08, deadline=deadline, rng=rng)
        if R > best_R:
            best_R = R
            best = h.copy()

    # Final polish on full-size
    if time.process_time() < deadline:
        best, best_R = local_search(best, best_R, iters=8, step0=0.03,
                                    deadline=deadline, rng=rng)

    return np.asarray(best, dtype=float)

