import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def compute_R(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    num = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    den = s * s * np.max(L)
    if den <= 0:
        return -1.0
    return num / den


def _corr(a, h):
    n = h.size
    full = fftconvolve(a, h[::-1], mode='full')
    return full[n - 1: n - 1 + n]


def _R_grad(h):
    n = h.size
    s = h.sum()
    c = fftconvolve(h, h, mode='full')
    L = np.concatenate(([0.0], c, [0.0]))
    dA_dL = (np.concatenate(([0.0], L[:-1])) + 4.0 * L
             + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:1 + c.size]
    dA_dh = 2.0 * _corr(dA_dc, h)

    A = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0
    M = np.max(L)
    tol = 1e-13 * max(M, 1e-300)
    maxknots = np.flatnonzero(L >= M - tol)
    dM_dc = np.zeros(c.size)
    for j in maxknots:
        if 1 <= j <= c.size:
            dM_dc[j - 1] += 1.0
    cnt = dM_dc.sum()
    if cnt > 0:
        dM_dc /= cnt
    dM_dh = 2.0 * _corr(dM_dc, h)

    B = s * s
    R = A / (B * M)
    dB_dh = 2.0 * s
    dR_dh = (dA_dh / (B * M)
             - A / (B * B * M) * dB_dh
             - A / (B * M * M) * dM_dh)
    return R, dR_dh


def _smooth_R_grad(h, tau):
    n = h.size
    s = h.sum()
    if s <= 0:
        return -1.0, np.zeros(n)
    c = fftconvolve(h, h, mode='full')
    L = np.concatenate(([0.0], c, [0.0]))
    dA_dL = (np.concatenate(([0.0], L[:-1])) + 4.0 * L
             + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:1 + c.size]
    dA_dh = 2.0 * _corr(dA_dc, h)
    A = np.sum(L[:-1] ** 2 + L[:-1] * L[1:] + L[1:] ** 2) / 3.0

    Lmax = np.max(L)
    w = np.exp((L - Lmax) / tau)
    w /= w.sum()
    Ms = np.sum(w * L)
    dMs_dL = w * (L - Ms) / tau + w
    dMs_dc = dMs_dL[1:1 + c.size]
    dMs_dh = 2.0 * _corr(dMs_dc, h)

    B = s * s
    R = A / (B * Ms)
    dB_dh = 2.0 * s
    dR_dh = (dA_dh / (B * Ms)
             - A / (B * B * Ms) * dB_dh
             - A / (B * Ms * Ms) * dMs_dh)
    return R, dR_dh


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 3.0)

    if start is not None:
        best = np.asarray(start, dtype=float).ravel().copy()
        if best.size == 0 or not np.all(np.isfinite(best)) or np.any(best < 0) \
                or best.sum() <= 0:
            best = np.ones(50)
    else:
        best = np.ones(50)

    best_R = compute_R(best)
    state = {'best': best.copy(), 'best_R': best_R}

    def try_candidate(h):
        h = np.asarray(h, dtype=float)
        if h.size == 0 or h.size > 50000:
            return False
        if not np.all(np.isfinite(h)) or np.any(h < 0) or h.sum() <= 0:
            return False
        r = compute_R(h)
        if r > state['best_R']:
            state['best_R'] = r
            state['best'] = h.copy()
            return True
        return False

