            s = h.sum()
            if s <= 0:
                return 1.0, np.zeros_like(u)
            if use_smooth:
                R, g = _smooth_R_grad(h, tau)
            else:
                R, g = _R_grad(h)
            if not np.isfinite(R):
                return 1.0, np.zeros_like(u)
            return -R, -g * (2.0 * u)

        def cb(u):
            h = u * u
            r = compute_R(h)
            if r > state['best_R']:
                state['best_R'] = r
                state['best'] = h.copy()
            if time.process_time() >= deadline:
                raise StopIteration

        h0 = h_start / max(h_start.max(), 1e-300)
        u0 = np.sqrt(np.maximum(h0, 0.0))
        try:
            res = minimize(fun, u0, jac=True, method='L-BFGS-B', callback=cb,
                           options={'maxiter': maxiter, 'ftol': 1e-15,
                                    'gtol': 1e-13})
            try_candidate(res.x * res.x)
        except StopIteration:
            pass
        except Exception:
            pass

    def upsample(h, N):
        x_old = np.linspace(0.0, 1.0, h.size)
        x_new = np.linspace(0.0, 1.0, N)
        return np.maximum(0.0, np.interp(x_new, x_old, h))

    start_h = state['best'].copy()
    taus_frac = [0.02, 0.005, 0.001, 0.0001]
    Ns = [1600, 1800, 1900, 2000, 2100, 2200, 2500, 3000]

    best_N = start_h.size
    best_h = start_h.copy()
    best_R_local = compute_R(start_h)

    for N in Ns:
        if time.process_time() >= deadline:
            break
