            optimize_at(h, 150, True, peak * tf)
            # use the best found so far at this N (state may be at other N)
            # Instead, track locally: re-run exact on current h
            # We need a local copy; use a local optimizer wrapper
            # Simpler: use state['best'] only if same size
            if state['best'].size == N:
                h = state['best'].copy()
            else:
                # do local exact step
                pass
        if time.process_time() >= deadline:
            break
        # exact-gradient stage
        # local exact optimization at this N
        def local_fun(u):
            hh = u * u
            if hh.sum() <= 0:
                return 1.0, np.zeros_like(u)
            R, g = _R_grad(hh)
            if not np.isfinite(R):
                return 1.0, np.zeros_like(u)
            return -R, -g * (2.0 * u)

        def local_cb(u):
            if time.process_time() >= deadline:
                raise StopIteration

        h0 = h / max(h.max(), 1e-300)
        u0 = np.sqrt(np.maximum(h0, 0.0))
        try:
            res = minimize(local_fun, u0, jac=True, method='L-BFGS-B',
                           callback=local_cb,
                           options={'maxiter': 500, 'ftol': 1e-15,
                                    'gtol': 1e-13})
            h = res.x * res.x
        except StopIteration:
            pass
        except Exception:
            pass
        r = compute_R(h)
        if r > best_R_local:
            best_R_local = r
            best_h = h.copy()
            best_N = N
        try_candidate(h)

    # Final exact polish at best N
    if time.process_time() < deadline:
        h = best_h.copy()
        def final_fun(u):
            hh = u * u
            if hh.sum() <= 0:
                return 1.0, np.zeros_like(u)
            R, g = _R_grad(hh)
            if not np.isfinite(R):
                return 1.0, np.zeros_like(u)
            return -R, -g * (2.0 * u)

        def final_cb(u):
            hh = u * u
            r = compute_R(hh)
            if r > state['best_R']:
                state['best_R'] = r
                state['best'] = hh.copy()
            if time.process_time() >= deadline:
                raise StopIteration

        h0 = h / max(h.max(), 1e-300)
        u0 = np.sqrt(np.maximum(h0, 0.0))
        try:
            res = minimize(final_fun, u0, jac=True, method='L-BFGS-B',
                           callback=final_cb,
                           options={'maxiter': 3000, 'ftol': 1e-15,
                                    'gtol': 1e-13})
            try_candidate(res.x * res.x)
        except StopIteration:
            pass
        except Exception:
            pass

    return state['best']

