        c = np.convolve(h, h)
        M = c.max()
        if M <= 0:
            return
        mask = c > 0.01 * M
        g_target = np.zeros_like(c)
        g_target[mask] = M * (c[mask] / M) ** p
        gt_norm2 = np.sum(g_target * g_target)
        if gt_norm2 <= 0:
            return

        def fun(u):
            hh = u * u
            if hh.sum() <= 0:
                return 1.0, np.zeros_like(u)
            cc = fftconvolve(hh, hh, mode='full')
            diff = cc - g_target
            F = np.sum(diff * diff) / gt_norm2
            # dF/dh = 2*corr(diff, h); dF/du = dF/dh * 2u
            g_h = 2.0 * _corr(diff, hh)
            g_u = g_h * (2.0 * u)
            if not np.isfinite(F):
                return 1.0, np.zeros_like(u)
            return F, g_u

        def cb(u):
            if time.process_time() >= deadline:
                raise StopIteration

        h0 = h / max(h.max(), 1e-300)
        u0 = np.sqrt(np.maximum(h0, 0.0))
        try:
            res = minimize(fun, u0, jac=True, method='L-BFGS-B', callback=cb,
                           options={'maxiter': maxiter, 'ftol': 1e-18,
                                    'gtol': 1e-16})
            try_candidate(res.x * res.x)
        except StopIteration:
            pass
        except Exception:
            pass

    # Initial polish at current resolution.
    optimize_at(state['best'], 500, False, 0.0)

    # Flattening cycles.
    for cycle in range(2):
        if time.process_time() >= deadline:
            break
        for p in (0.7, 0.5, 0.3):
            if time.process_time() >= deadline:
                break
            h_cur = state['best'].copy()
            flatten_fit(h_cur, p, 400)
            if time.process_time() >= deadline:
                break
            optimize_at(state['best'], 800, False, 0.0)
            if time.process_time() >= deadline:
                break
            cc = np.convolve(state['best'], state['best'])
            peak = cc.max()
            optimize_at(state['best'], 300, True, peak * 0.003)
            if time.process_time() >= deadline:
                break
            optimize_at(state['best'], 800, False, 0.0)

    # Final polish.
    if time.process_time() < deadline:
        optimize_at(state['best'], 3000, False, 0.0)

    return state['best']

