    L = np.concatenate(([0.0], c, [0.0]))
    dA_dL = (np.concatenate(([0.0], L[:-1])) + 4.0*L
             + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:1+c.size]
    dA_dh = 2.0 * _corr(dA_dc, h)
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    M = np.max(L)
    tol = 1e-13 * max(M, 1e-300)
    maxknots = np.flatnonzero(L >= M - tol)
    dM_dc = np.zeros(c.size)
    for j in maxknots:
        if 1 <= j <= c.size:
            dM_dc[j-1] += 1.0
    cnt = dM_dc.sum()
    if cnt > 0:
        dM_dc /= cnt
    dM_dh = 2.0 * _corr(dM_dc, h)
    B = s * s
    R = A / (B * M)
    dB_dh = 2.0 * s
    dR_dh = (dA_dh/(B*M) - A/(B*B*M)*dB_dh - A/(B*M*M)*dM_dh)
    return R, dR_dh


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 2.5)

    if start is not None:
        best = np.asarray(start, dtype=float).ravel().copy()
        if best.size == 0 or not np.all(np.isfinite(best)) or np.any(best < 0) \
                or best.sum() <= 0:
            best = np.ones(50)
    else:
        best = np.ones(50)

    best_R = compute_R(best)
    orig = best.copy()
    orig_R = best_R

    def try_candidate(h):
        nonlocal best, best_R
        h = np.asarray(h, dtype=float)
        if h.size == 0 or h.size > 50000:
            return False
        if not np.all(np.isfinite(h)) or np.any(h < 0) or h.sum() <= 0:
            return False
        r = compute_R(h)
        if r > best_R:
            best_R = r
            best = h.copy()
            return True
        return False

    def optimize_at(h_start, maxiter):
        def fun(u):
            h = u * u
            if h.sum() <= 0:
                return 1.0, np.zeros_like(u)
            R, g = _R_grad(h)
            if not np.isfinite(R):
                return 1.0, np.zeros_like(u)
            return -R, -g * (2.0 * u)

        def cb(u):
            r = compute_R(u * u)
            if r > best_R:
                try_candidate(u * u)
            if time.process_time() >= deadline:
                raise StopIteration

        h0 = h_start / max(h_start.max(), 1e-300)
        u0 = np.sqrt(np.maximum(h0, 0.0))
        try:
            res = minimize(fun, u0, jac=True, method='L-BFGS-B', callback=cb,
                           options={'maxiter': maxiter, 'ftol': 1e-16,
                                    'gtol': 1e-14})
            try_candidate(res.x * res.x)
        except StopIteration:
            pass
        except Exception:
            pass

    def upsample(h, N):
        x_old = np.linspace(0.0, 1.0, h.size)
        x_new = np.linspace(0.0, 1.0, N)
        return np.maximum(0.0, np.interp(x_new, x_old, h))

    def block_average(h, factor):
        n = h.size
        m = n // factor
        if m < 1:
            return h.copy()
        h = h[:m*factor].reshape(m, factor)
        return h.mean(axis=1)

    # Experiment: fine grid -> downsample -> polish.
    for N_fine, factor in ((20000, 10), (10000, 5)):
        if time.process_time() >= deadline:
            break
        h_fine = upsample(orig, N_fine)
        try_candidate(h_fine)
        optimize_at(h_fine, 1200)
        if time.process_time() >= deadline:
            break
        # Use the fine-optimized shape (fall back to h_fine if not improved).
        fine_best = best if best.size == N_fine else h_fine
        h_down = block_average(fine_best, factor)
        try_candidate(h_down)
        optimize_at(h_down, 2000)

    # Final polish at whatever best resolution we have.
    if time.process_time() < deadline:
        optimize_at(best, 2000)

    # Keep best vs original.
    if orig_R >= best_R:
        best = orig
        best_R = orig_R

    print("final R =", best_R, "N =", best.size)
    return best

