        h = np.asarray(h, dtype=float)
        if h.size == 0 or h.size > 50000:
            return False
        if not np.all(np.isfinite(h)) or np.any(h < 0) or h.sum() <= 0:
            return False
        r = compute_R(h)
        if r > state['best_R']:
            state['best_R'] = r
            state['best'] = h.copy()
            return True
        return False

    def optimize_at(h_start, maxiter, use_smooth, tau):
        def fun(u):
            h = u * u
            if h.sum() <= 0:
                return 1.0, np.zeros_like(u)
            if use_smooth:
                R, g = _smooth_R_grad(h, tau)
            else:
                R, g = _R_grad(h)
            if not np.isfinite(R):
                return 1.0, np.zeros_like(u)
            return -R, -g * (2.0 * u)

        def cb(u):
            r = compute_R(u * u)
            if r > state['best_R']:
                state['best_R'] = r
                state['best'] = (u * u).copy()
            if time.process_time() >= deadline:
                raise StopIteration

        h0 = h_start / max(h_start.max(), 1e-300)
        u0 = np.sqrt(np.maximum(h0, 0.0))
        try:
            res = minimize(fun, u0, jac=True, method='L-BFGS-B', callback=cb,
                           options={'maxiter': maxiter, 'ftol': 1e-16,
                                    'gtol': 1e-14})
            try_candidate(res.x * res.x)
        except StopIteration:
            pass
        except Exception:
            pass

    # Start with the given start, refine at its own N.
    if time.process_time() < deadline:
        optimize_at(state['best'], 800, False, 0.0)

    # Refine with smoothed max at a few scales.
    for tf in (0.01, 0.002, 0.0004, 8e-5):
        if time.process_time() >= deadline:
            break
        cc = np.convolve(state['best'], state['best'])
        peak = cc.max()
        optimize_at(state['best'], 400, True, peak * tf)
        if time.process_time() >= deadline:
            break
        optimize_at(state['best'], 500, False, 0.0)

    # Coarse-to-fine ladder: rebuild at finer N and re-optimize.
    base_N = state['best'].size
    targets = []
    for N in (2000, 3000, 4000, 6000, 8000):
        if N > base_N and N <= 50000:
            targets.append(N)
    for N in targets:
        if time.process_time() >= deadline:
            break
        h_up = _resample(state['best'], N)
        try_candidate(h_up)
        cc = np.convolve(h_up, h_up)
        peak = cc.max()
        optimize_at(h_up, 300, True, peak * 0.005)
        if time.process_time() >= deadline:
            break
        optimize_at(state['best'], 400, False, 0.0)

    # Final polishing with progressively sharper smoothing.
    for tf in (0.0003, 6e-5, 1.5e-5):
        if time.process_time() >= deadline:
            break
        cc = np.convolve(state['best'], state['best'])
        peak = cc.max()
        optimize_at(state['best'], 400, True, peak * tf)
        if time.process_time() >= deadline:
            break
        optimize_at(state['best'], 600, False, 0.0)

    if time.process_time() < deadline:
        optimize_at(state['best'], 3000, False, 0.0)

    print("final R:", state['best_R'], "N:", state['best'].size)
    return state['best']

