            optimize_at(state['best'], 800, False, 0.0)
        if time.process_time() >= deadline:
            break
        optimize_at(state['best'], 1500, False, 0.0)
        print("N =", N, "best R =", state['best_R'], "best N =", state['best'].size)

    # Final polish at the very best resolution found.
    if time.process_time() < deadline:
