    def block_ascent(h_in, deadline):
        h = h_in.copy()
        n = h.size
        bestR = compute_R(h)
        block_sizes = [1, 2, 4, 8, 16, 32, 64, 128]

        def eval_scale(h, i0, i1, t):
            hh = h.copy()
            hh[i0:i1] *= t
            return compute_R(hh)

        def ternary(h, i0, i1, lo=0.9, hi=1.1, iters=8):
            for _ in range(iters):
                if time.process_time() >= deadline:
                    return 1.0
                m1 = lo + (hi - lo) / 3.0
                m2 = hi - (hi - lo) / 3.0
                r1 = eval_scale(h, i0, i1, m1)
                r2 = eval_scale(h, i0, i1, m2)
                if r1 < r2:
                    lo = m1
                else:
                    hi = m2
            return 0.5 * (lo + hi)

        sweep_count = 0
        while time.process_time() < deadline:
            improved_any = False
            for B in block_sizes:
                if time.process_time() >= deadline:
                    break
                i = 0
                while i < n:
                    if time.process_time() >= deadline:
                        break
                    i1 = min(i + B, n)
                    if i1 <= i:
                        i += B
                        continue
                    t = ternary(h, i, i1)
                    if t != 1.0:
                        hh = h.copy()
                        hh[i:i1] *= t
                        r = compute_R(hh)
                        if r > bestR + 1e-15:
                            h = hh
                            bestR = r
                            improved_any = True
                    i += B
            sweep_count += 1
            print("block sweep", sweep_count, "bestR", bestR)
            if not improved_any:
                break
        return h, bestR

    if time.process_time() < deadline:
        h2000 = _resample(state['best'], 2000)
        try_candidate(h2000)
        hb, rb = block_ascent(state['best'] if state['best'].size == 2000
                              else h2000, deadline)
        try_candidate(hb)
        print("after block ascent R =", state['best_R'], "N =", state['best'].size)

    # Final exact-polish loop at the best N found, with tiny smoothing bumps
    for _ in range(10):
        if time.process_time() >= deadline:
            break
        cc = np.convolve(state['best'], state['best'])
        peak = cc.max()
        optimize_at(state['best'], 500, True, peak * 3e-5)
        if time.process_time() >= deadline:
            break
        optimize_at(state['best'], 3000, False, 0.0)

    print("final R =", state['best_R'], "N =", state['best'].size)
    return state['best']

