    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 2.5)

    if start is not None:
        base = np.asarray(start, dtype=float).ravel().copy()
        if base.size == 0 or not np.all(np.isfinite(base)) or np.any(base < 0) \
                or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)

    state = {'best': base.copy(), 'best_R': compute_R(base)}

    def try_candidate(h):
        h = np.asarray(h, dtype=float)
        if h.size == 0 or h.size > 50000:
            return False
        if not np.all(np.isfinite(h)) or np.any(h < 0) or h.sum() <= 0:
            return False
        r = compute_R(h)
        if r > state['best_R']:
            state['best_R'] = r
            state['best'] = h.copy()
            return True
        return False

    def optimize_at(h_start, maxiter, use_smooth, tau):
        def fun(u):
            h = u * u
            if h.sum() <= 0:
                return 1.0, np.zeros_like(u)
            if use_smooth:
                R, g = _smooth_R_grad(h, tau)
            else:
                R, g = _R_grad(h)
            if not np.isfinite(R):
                return 1.0, np.zeros_like(u)
            return -R, -g * (2.0 * u)

        def cb(u):
            r = compute_R(u * u)
            if r > state['best_R']:
                state['best_R'] = r
                state['best'] = (u * u).copy()
            if time.process_time() >= deadline:
                raise StopIteration

        h0 = h_start / max(h_start.max(), 1e-300)
        u0 = np.sqrt(np.maximum(h0, 0.0))
        try:
            res = minimize(fun, u0, jac=True, method='L-BFGS-B', callback=cb,
                           options={'maxiter': maxiter, 'ftol': 1e-16,
                                    'gtol': 1e-14})
            try_candidate(res.x * res.x)
        except StopIteration:
            pass
        except Exception:
            pass

    baseN = int(base.size)
    # Prefer tightening at the current N first, then explore neighbours.
    Ns = []
    for d in [0, 1, -1, 2, -2, 4, -4, 8, -8]:
        n = baseN + d
        if 50 <= n <= 50000 and n not in Ns:
            Ns.append(n)

    taus = [3e-4, 1e-4, 5e-5, 2e-5, 1e-5, 5e-6, 2e-6, 1e-6, 5e-7, 2e-7,
            1e-7, 5e-8, 2e-8, 1e-8]

    for N in Ns:
        if time.process_time() >= deadline:
            break
        h_up = _resample(base, N)
        try_candidate(h_up)
        optimize_at(h_up, 6000, False, 0.0)
        for tf in taus:
            if time.process_time() >= deadline:
                break
            cc = np.convolve(state['best'], state['best'])
            peak = cc.max()
            optimize_at(state['best'], 600, True, peak * tf)
            if time.process_time() >= deadline:
                break
            optimize_at(state['best'], 2000, False, 0.0)
        if time.process_time() >= deadline:
            break
        print("N =", N, "best R =", state['best_R'], "best N =", state['best'].size)

    # Final extended exact-polish loop at the best N found.
    for _ in range(40):
        if time.process_time() >= deadline:
            break
        cc = np.convolve(state['best'], state['best'])
        peak = cc.max()
        optimize_at(state['best'], 500, True, peak * 3e-7)
        if time.process_time() >= deadline:
            break
        optimize_at(state['best'], 5000, False, 0.0)

    print("final R =", state['best_R'], "N =", state['best'].size)
    return state['best']

