        return -R, -g * (2.0 * u)

    def hessp(u, p):
        # finite-difference Hessian-vector product on the u-space
        eps = 1e-6
        _, g0 = fun(u)
        _, g1 = fun(u + eps * p)
        return (g1 - g0) / eps

    u0 = np.sqrt(h0)
    try:
        res = minimize(fun, u0, jac=True, method='Newton-CG', hessp=hessp,
                       options={'maxiter': maxiter, 'xtol': 1e-12, 'gtol': 1e-12})
        out = res.x * res.x
        if np.all(np.isfinite(out)) and out.sum() > 0:
            return out
    except Exception:
        pass
    return h0


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 2.5)

    if start is not None:
        base = np.asarray(start, dtype=float).ravel().copy()
        if base.size == 0 or not np.all(np.isfinite(base)) or np.any(base < 0) \
                or base.sum() <= 0:
