    else:
        base = np.ones(50)

    state = {'best': base.copy(), 'best_R': compute_R(base)}

    def try_candidate(h):
        h = np.asarray(h, dtype=float)
        if h.size == 0 or h.size > 50000:
            return False
        if not np.all(np.isfinite(h)) or np.any(h < 0) or h.sum() <= 0:
            return False
        r = compute_R(h)
        if r > state['best_R']:
            state['best_R'] = r
            state['best'] = h.copy()
            return True
        return False

    def optimize_at(h_start, maxiter, use_smooth, tau):
        def fun(u):
            h = u * u
            if h.sum() <= 0:
                return 1.0, np.zeros_like(u)
            if use_smooth:
                R, g = _smooth_R_grad(h, tau)
            else:
                R, g = _R_grad(h)
            if not np.isfinite(R):
                return 1.0, np.zeros_like(u)
            return -R, -g * (2.0 * u)

        def cb(u):
            r = compute_R(u * u)
            if r > state['best_R']:
                state['best_R'] = r
                state['best'] = (u * u).copy()
            if time.process_time() >= deadline:
                raise StopIteration

        h0 = h_start / max(h_start.max(), 1e-300)
        u0 = np.sqrt(np.maximum(h0, 0.0))
        try:
            res = minimize(fun, u0, jac=True, method='L-BFGS-B', callback=cb,
                           options={'maxiter': maxiter, 'ftol': 1e-16,
                                    'gtol': 1e-14})
            try_candidate(res.x * res.x)
        except StopIteration:
            pass
        except Exception:
            pass

    # Phase 1: sharpen the current best at its native size.
    optimize_at(state['best'], 4000, False, 0.0)
    print("phase1 R =", state['best_R'], "N =", state['best'].size)

    # Phase 1.5 (experiment): finer-grid exploration + Newton-CG + block-average back.
    for N in [3000, 4000, 6000]:
        if time.process_time() >= deadline:
            break
        h_up = _resample(state['best'], N)
        if not try_candidate(h_up):
            # still optimise from the upsampled version
            pass
        optimize_at(state['best'], 3000, False, 0.0)
        if time.process_time() >= deadline:
            break
        h_nc = _newton_cg(state['best'], 100, deadline)
        try_candidate(h_nc)
