        before = state['best_R']
        ladder_at(N)
        if state['best_R'] > before:
            best_coarse_N = N

    # Fine pass around best coarse N
    fine_offsets = [1, 2, 3, 5, 8, 13, 21, 34]
    fine_Ns = []
    for d in fine_offsets:
        for sgn in (1, -1):
