    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    den = s * s * np.max(L)
    if den <= 0:
        return -1.0
    return num / den


def _corr(a, h):
    n = h.size
    full = fftconvolve(a, h[::-1], mode='full')
    return full[n-1:n-1+n]


def _R_grad(h):
    n = h.size
    s = h.sum()
    c = fftconvolve(h, h, mode='full')
    L = np.concatenate(([0.0], c, [0.0]))
    dA_dL = (np.concatenate(([0.0], L[:-1])) + 4.0*L
             + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:1+c.size]
    dA_dh = 2.0 * _corr(dA_dc, h)
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    M = np.max(L)
    tol = 1e-13 * max(M, 1e-300)
    maxknots = np.flatnonzero(L >= M - tol)
    dM_dc = np.zeros(c.size)
    for j in maxknots:
        if 1 <= j <= c.size:
            dM_dc[j-1] += 1.0
    cnt = dM_dc.sum()
    if cnt > 0:
        dM_dc /= cnt
    dM_dh = 2.0 * _corr(dM_dc, h)
    B = s * s
    R = A / (B * M)
    dB_dh = 2.0 * s
    dR_dh = (dA_dh/(B*M) - A/(B*B*M)*dB_dh - A/(B*M*M)*dM_dh)
    return R, dR_dh


def _pnorm_R_grad(h, p):
    n = h.size
    s = h.sum()
    if s <= 0:
        return -1.0, np.zeros(n)
    c = fftconvolve(h, h, mode='full')
    L = np.concatenate(([0.0], c, [0.0]))
    dA_dL = (np.concatenate(([0.0], L[:-1])) + 4.0*L
             + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:1+c.size]
    dA_dh = 2.0 * _corr(dA_dc, h)
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    Lsafe = np.maximum(L, 1e-300)
    Mp = np.mean(Lsafe**p)
    M = Mp**(1.0/p)
    dM_dL = (1.0/L.size) * (Lsafe/M)**(p-1.0)
    dM_dc = dM_dL[1:1+c.size]
    dM_dh = 2.0 * _corr(dM_dc, h)
    B = s * s
    R = A / (B * M)
    dB_dh = 2.0 * s
    dR_dh = (dA_dh/(B*M) - A/(B*B*M)*dB_dh - A/(B*M*M)*dM_dh)
    return R, dR_dh


