                R, g = _smooth_R_grad(h, tau)
            else:
                R, g = _R_grad(h)
            if not np.isfinite(R):
                return 1.0, np.zeros_like(u)
            return -R, -g * (2.0 * u)

        def cb(u):
            r = compute_R(u * u)
            if r > state['best_R']:
                state['best_R'] = r
                state['best'] = (u * u).copy()
            if time.process_time() >= deadline:
                raise StopIteration

