        peak = cc.max()
        optimize_at(state['best'], 800, True, peak * tf)
        if time.process_time() >= deadline:
            break
        optimize_at(state['best'], 1500, False, 0.0)
    print("phase3 R =", state['best_R'])

    # Phase 4: coordinate-wise random block bump polish.
    def perturb_polish():
        rng = np.random.default_rng(98765)
        N = state['best'].size
        if N < 4:
            return
        u = np.sqrt(np.maximum(state['best'], 0.0))
        bestR = state['best_R']
        step = 2e-3
        for it in range(400):
            if time.process_time() >= deadline:
                return
            L = int(rng.integers(2, max(3, N // 3)))
            if L >= N:
                L = N - 1
            a = int(rng.integers(0, N - L))
            v = u.copy()
            x = np.linspace(-1.0, 1.0, L)
            shape = np.cos(np.pi * x * 0.5) ** 2
            amp = step * (rng.random() * 2 - 1)
            v[a:a+L] += amp * shape * (u[a:a+L] + 1e-3)
