            state['best_R'] = bestR
            state['best'] = (u * u).copy()

    if time.process_time() < deadline:
        perturb_polish()
    print("phase4 R =", state['best_R'])

    # Phase 5: final exact polish and re-polish loop until deadline.
    while time.process_time() < deadline:
