import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def compute_R(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    den = s * s * np.max(L)
    if den <= 0:
        return -1.0
    return num / den


def _corr(a, h):
    n = h.size
    full = fftconvolve(a, h[::-1], mode='full')
    return full[n-1:n-1+n]


def _grad_common(h, weight_fn):
    n = h.size
    s = h.sum()
    c = fftconvolve(h, h, mode='full')
    L = np.concatenate(([0.0], c, [0.0]))
    dA_dL = (np.concatenate(([0.0], L[:-1])) + 4.0*L
             + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:1+c.size]
    dA_dh = 2.0 * _corr(dA_dc, h)
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    Ms, dMs_dL = weight_fn(L, c)
    dMs_dc = dMs_dL[1:1+c.size]
    dMs_dh = 2.0 * _corr(dMs_dc, h)
    B = s * s
    R = A / (B * Ms)
    dB_dh = 2.0 * s
    dR_dh = (dA_dh/(B*Ms) - A/(B*B*Ms)*dB_dh - A/(B*Ms*Ms)*dMs_dh)
    return R, dR_dh


def _R_grad(h):
    def wf(L, c):
        M = np.max(L)
        tol = 1e-12 * max(M, 1e-300)
        mask = (L >= M - tol).astype(float)
        return M, mask
    return _grad_common(h, wf)


def _pnorm_R_grad(h, p):
    def wf(L, c):
        Ls = np.maximum(L, 1e-300)
        Mp = np.mean(Ls**p)
        M = Mp**(1.0/p)
        dM_dL = (1.0/L.size) * (Ls/M)**(p-1.0)
        return M, dM_dL
    return _grad_common(h, wf)


def _smooth_R_grad(h, tau):
    def wf(L, c):
        Lmax = np.max(L)
        w = np.exp((L - Lmax) / tau)
        w /= w.sum()
        Ms = np.sum(w * L)
        dMs_dL = w * (L - Ms) / tau + w
        return Ms, dMs_dL
    return _grad_common(h, wf)


def _resample(h, N):
    if h.size == N:
        return h.copy()
    if N > h.size:
        x_old = np.linspace(0.0, 1.0, h.size)
        x_new = np.linspace(0.0, 1.0, N)
        return np.maximum(0.0, np.interp(x_new, x_old, h))
    out = np.empty(N)
    edges = np.linspace(0, h.size, N + 1)
    for i in range(N):
        a = int(np.floor(edges[i]))
        b = int(np.ceil(edges[i + 1]))
        b = max(b, a + 1)
        out[i] = h[a:b].mean()
    return np.maximum(0.0, out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 3.0)

    if start is not None:
        base = np.asarray(start, dtype=float).ravel().copy()
        if base.size == 0 or not np.all(np.isfinite(base)) or np.any(base < 0) \
                or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)

    state = {'best': base.copy(), 'best_R': compute_R(base)}

    def try_candidate(h):
        h = np.asarray(h, dtype=float)
        if h.size == 0 or h.size > 50000:
            return False
        if not np.all(np.isfinite(h)) or np.any(h < 0) or h.sum() <= 0:
            return False
        r = compute_R(h)
        if r > state['best_R']:
            state['best_R'] = r
            state['best'] = h.copy()
            return True
        return False

    def optimize_at(h_start, maxiter, mode, param):
        def fun(u):
            h = u * u
            if h.sum() <= 0:
                return 1.0, np.zeros_like(u)
            if mode == 'smooth':
                R, g = _smooth_R_grad(h, param)
            elif mode == 'pnorm':
                R, g = _pnorm_R_grad(h, param)
            else:
                R, g = _R_grad(h)
            if not np.isfinite(R):
                return 1.0, np.zeros_like(u)
            return -R, -g * (2.0 * u)

        def cb(u):
            r = compute_R(u * u)
            if r > state['best_R']:
                state['best_R'] = r
                state['best'] = (u * u).copy()
            if time.process_time() >= deadline:
                raise StopIteration

        h0 = h_start / max(h_start.max(), 1e-300)
        u0 = np.sqrt(np.maximum(h0, 0.0))
        try:
            res = minimize(fun, u0, jac=True, method='L-BFGS-B', callback=cb,
                           options={'maxiter': maxiter, 'ftol': 1e-17,
                                    'gtol': 1e-15})
            try_candidate(res.x * res.x)
        except StopIteration:
            pass
        except Exception:
            pass

    # Phase 1: sharpen the current best at its native size.
    optimize_at(state['best'], 6000, 'exact', 0.0)
    print("phase1 R =", state['best_R'], "N =", state['best'].size)

    # Phase 2: p-norm continuation to sharpen the peak (works well near plateaus).
    baseN = state['best'].size
    for p in [4, 8, 16, 32, 64, 128, 256, 512]:
        if time.process_time() >= deadline:
            break
        optimize_at(state['best'], 400, 'pnorm', p)
    if time.process_time() < deadline:
        optimize_at(state['best'], 4000, 'exact', 0.0)
    print("phase2 R =", state['best_R'])

    # Phase 3: softmax ladder to escape the plateau around the max.
    taus = [3e-3, 1e-3, 3e-4, 1e-4, 5e-5, 2e-5, 1e-5, 5e-6, 2e-6, 1e-6, 5e-7]
    for tf in taus:
        if time.process_time() >= deadline:
            break
        cc = np.convolve(state['best'], state['best'])
        peak = cc.max()
        before = state['best_R']
        optimize_at(state['best'], 800, 'smooth', peak * tf)
        if time.process_time() >= deadline:
            break
        optimize_at(state['best'], 2000, 'exact', 0.0)
        print("tau", tf, "R =", state['best_R'])
        if time.process_time() >= deadline:
            break

    # Phase 4: try slight size variations around the best N.
    baseN = state['best'].size
    for d in [1, -1, 2, -2, 3, -3, 5, -5]:
        if time.process_time() >= deadline:
            break
        n = baseN + d
        if 50 <= n <= 50000:
            h_up = _resample(state['best'], n)
            if try_candidate(h_up):
                optimize_at(state['best'], 2000, 'exact', 0.0)
    print("phase4 R =", state['best_R'], "N =", state['best'].size)

    # Phase 5: final exact polish until deadline.
    while time.process_time() < deadline:
        before = state['best_R']
        optimize_at(state['best'], 5000, 'exact', 0.0)
        if state['best_R'] <= before:
            break
    print("final R =", state['best_R'], "N =", state['best'].size)
    return state['best']

