    for N in cand_Ns:
        if time.process_time() >= deadline:
            break
        h_up = _resample(state['best'], N)
        if try_candidate(h_up):
            optimize_at(state['best'], 3000, False, 0.0)
        print("N =", N, "R =", state['best_R'])

    # Phase 3: softmax polishes.
    taus = [1e-3, 3e-4, 1e-4, 5e-5, 2e-5, 1e-5, 5e-6, 1e-6, 3e-7]
    for tf in taus:
        if time.process_time() >= deadline:
            break
        cc = np.convolve(state['best'], state['best'])
        peak = cc.max()
        optimize_at(state['best'], 800, True, peak * tf)
        if time.process_time() >= deadline:
            break
        optimize_at(state['best'], 1500, False, 0.0)
    print("phase3 R =", state['best_R'])

    # Phase 4: multi-scale simulated annealing in sqrt space.
    def sa_polish():
        rng = np.random.default_rng(987654321)
        N = state['best'].size
        if N < 4:
            return
        u = np.sqrt(np.maximum(state['best'], 0.0))
        cur_h = u * u
        cur_R = compute_R(cur_h)
        best_h = cur_h.copy()
        best_R = cur_R
        temps = [3e-3, 1e-3, 3e-4, 1e-4, 3e-5]
        block_lens = [2, 4, 8, 16, 32, 64, 128]
        amps = [1e-2, 3e-3, 1e-3, 3e-4]
        for T in temps:
            for it in range(300):
                if time.process_time() >= deadline:
                    break
                L = int(block_lens[int(rng.integers(0, len(block_lens)))])
                L = min(L, N)
                if L < 1:
                    continue
                a = int(rng.integers(0, max(1, N - L + 1)))
                amp = float(amps[int(rng.integers(0, len(amps)))])
                sign = 1.0 if rng.random() < 0.5 else -1.0
                x = np.linspace(-1.0, 1.0, L)
                shape = np.cos(np.pi * x * 0.5) ** 2
                v = u.copy()
                v[a:a+L] += sign * amp * shape * (u[a:a+L] + 1e-3)
                v = np.maximum(v, 0.0)
                hn = v * v
                r = compute_R(hn)
                if r < 0:
                    continue
                dR = r - cur_R
                accept = False
                if dR > 0:
                    accept = True
                else:
                    if T > 0:
                        p = np.exp(dR / T)
                        if rng.random() < p:
                            accept = True
                if accept:
                    u = v
                    cur_h = hn
                    cur_R = r
                    if r > best_R:
                        best_R = r
                        best_h = hn.copy()
                        if r > state['best_R']:
                            state['best_R'] = r
                            state['best'] = hn.copy()
                if it % 25 == 24:
                    if time.process_time() >= deadline:
                        break
                    optimize_at(state['best'], 300, False, 0.0)
                    # resync SA state with the (possibly improved) best
                    if state['best_R'] > best_R:
                        best_R = state['best_R']
                        best_h = state['best'].copy()
                    u = np.sqrt(np.maximum(best_h, 0.0))
                    cur_h = best_h.copy()
                    cur_R = best_R
            if time.process_time() >= deadline:
                break
        if best_R > state['best_R']:
            state['best_R'] = best_R
            state['best'] = best_h.copy()

    if time.process_time() < deadline:
