        kk = min(max(1, int(k)), n)
        idx = np.argpartition(L, n - kk)[n - kk:]
        M = L[idx].mean()
        dMs_dL = np.zeros(n)
        dMs_dL[idx] = 1.0 / kk
        return M, dMs_dL
    return _grad_common(h, wf)


def _resample(h, N):
    if h.size == N:
        return h.copy()
