            if odd:
                return np.concatenate((m, m[-2::-1]))
            return np.concatenate((m, m[::-1]))

        def fun(u):
            h = expand(u)
            if h.sum() <= 0:
                return 1.0, np.zeros_like(u)
            R, g = _R_grad(h)
            if not np.isfinite(R):
