        if r > state['best_R']:
            state['best_R'] = r
            state['best'] = h.copy()
            return True
        return False

    def optimize_at(h_start, maxiter, use_smooth, tau):
        def fun(u):
            h = u * u
            if h.sum() <= 0:
                return 1.0, np.zeros_like(u)
            if use_smooth:
                R, g = _smooth_R_grad(h, tau)
            else:
                R, g = _R_grad(h)
            if not np.isfinite(R):
                return 1.0, np.zeros_like(u)
            return -R, -g * (2.0 * u)

        def cb(u):
            r = compute_R(u * u)
            if r > state['best_R']:
                state['best_R'] = r
                state['best'] = (u * u).copy()
            if time.process_time() >= deadline:
                raise StopIteration

        h0 = h_start / max(h_start.max(), 1e-300)
        u0 = np.sqrt(np.maximum(h0, 0.0))
        try:
            res = minimize(fun, u0, jac=True, method='L-BFGS-B', callback=cb,
                           options={'maxiter': maxiter, 'ftol': 1e-16,
                                    'gtol': 1e-14})
            try_candidate(res.x * res.x)
        except StopIteration:
            pass
        except Exception:
            pass

    def optimize_topk(h_start, maxiter, k):
        def fun(u):
            h = u * u
            if h.sum() <= 0:
                return 1.0, np.zeros_like(u)
            R, g = _topk_R_grad(h, k)
            if not np.isfinite(R):
                return 1.0, np.zeros_like(u)
            return -R, -g * (2.0 * u)

        def cb(u):
            r = compute_R(u * u)
            if r > state['best_R']:
