            pass
        except Exception:
            pass

    def optimize_symmetric(h_start, maxiter):
        N = h_start.size
        half = (N + 1) // 2
        odd = (N % 2 == 1)

        def expand(u):
            m = u * u
            if odd:
                return np.concatenate((m, m[-2::-1]))
            return np.concatenate((m, m[::-1]))

