        half = (N + 1) // 2
        odd = (N % 2 == 1)

        def expand(u):
            m = u * u
            if odd:
                return np.concatenate((m, m[-2::-1]))
            return np.concatenate((m, m[::-1]))

        def fun(u):
            h = expand(u)
            if h.sum() <= 0:
                return 1.0, np.zeros_like(u)
            R, g = _topk_R_grad(h, k)
            if not np.isfinite(R):
                return 1.0, np.zeros_like(u)
            gu = np.empty_like(u)
            if odd:
                c = half - 1
                for i in range(c):
                    gu[i] = 2.0 * u[i] * (g[i] + g[N - 1 - i])
                gu[c] = 2.0 * u[c] * g[c]
            else:
                for i in range(half):
                    gu[i] = 2.0 * u[i] * (g[i] + g[N - 1 - i])
            return -R, -gu

        def cb(u):
