            return np.concatenate((v, v[-2::-1]))

        def fun(u):
            v = u * u
            h = expand(v)
            if h.sum() <= 0:
                return 1.0, np.zeros_like(u)
            if use_smooth:
                R, g = _smooth_R_grad(h, tau)
            else:
                R, g = _R_grad(h)
            if not np.isfinite(R):
                return 1.0, np.zeros_like(u)
            gv = g[:m].copy()
            if N % 2 == 0:
                gv += g[m:][::-1]
            else:
                gv[1:] += g[m:][::-1]
            return -R, -gv * (2.0 * u)

        def cb(u):
            h = expand(u * u)
            r = compute_R(h)
            if r > state['best_R']:
