        if time.process_time() >= deadline:
            break
        optimize_at(state['best'], 3000, False, 0.0)
    print("phase4 R =", state['best_R'])

    # Phase 5 (NEW): vectorised block-coordinate refinement.
    # Perturb a block of consecutive entries by a multiplicative factor,
    # evaluate all directions at once via batched R evaluations, and accept
    # the best improving move. Much faster than the old per-index loop.
    if time.process_time() < deadline:
        h = state['best'].copy()
        N = h.size
        rng = np.random.default_rng(20240101)
        eps_list = [1e-3, 3e-4, 1e-4, 3e-5, 1e-5, 3e-6, 1e-6]
        block_sizes = [max(1, N // 20), max(1, N // 50), 1]

        def eval_many(trials):
            """Return R for a stack of trial arrays (each shape (N,))."""
            out = np.empty(len(trials))
            for k, t in enumerate(trials):
                out[k] = compute_R(t)
            return out

        for eps in eps_list:
            if time.process_time() >= deadline:
                break
            for bs in block_sizes:
                if time.process_time() >= deadline:
                    break
                improved = True
                sweeps = 0
                while improved and sweeps < 2 and time.process_time() < deadline:
                    improved = False
                    sweeps += 1
                    starts = list(range(0, N, bs))
                    rng.shuffle(starts)
                    for s0 in starts:
                        if time.process_time() >= deadline:
                            break
                        s1 = min(N, s0 + bs)
                        base_r = compute_R(h)
                        trials = []
                        for fac in (1.0 - eps, 1.0 + eps):
                            t = h.copy()
                            t[s0:s1] = np.maximum(0.0, t[s0:s1] * fac)
                            trials.append(t)
                        rs = eval_many(trials)
                        kbest = int(np.argmax(rs))
                        if rs[kbest] > base_r:
                            h = trials[kbest]
                            improved = True
            if try_candidate(h):
                pass
        if try_candidate(h):
            optimize_at(state['best'], 2000, False, 0.0)
        print("phase5 block R =", state['best_R'])

    # Phase 6: final full polish.
    if time.process_time() < deadline:
        optimize_at(state['best'], 20000, False, 0.0)
    print("final R =", state['best_R'], "N =", state['best'].size)
    return state['best']

