    def optimize_symmetric(h_start, maxiter, use_smooth=False, tau=0.0):
        N = h_start.size
        m = (N + 1) // 2
        h0 = h_start / max(h_start.max(), 1e-300)
        v0 = np.sqrt(np.maximum(h0[:m], 0.0))

        def expand(v):
            if N % 2 == 0:
                return np.concatenate((v, v[::-1]))
            return np.concatenate((v, v[-2::-1]))

        def fun(u):
            v = u * u
            h = expand(v)
            if h.sum() <= 0:
                return 1.0, np.zeros_like(u)
            if use_smooth:
                R, g = _smooth_R_grad(h, tau)
            else:
                R, g = _R_grad(h)
            if not np.isfinite(R):
                return 1.0, np.zeros_like(u)
            gv = g[:m].copy()
            if N % 2 == 0:
                gv += g[m:][::-1]
            else:
                gv[1:] += g[m:][::-1]
            return -R, -gv * (2.0 * u)

        def cb(u):
            h = expand(u * u)
            r = compute_R(h)
            if r > state['best_R']:
                state['best_R'] = r
                state['best'] = h.copy()
            if time.process_time() >= deadline:
                raise StopIteration

        try:
            res = minimize(fun, v0, jac=True, method='L-BFGS-B', callback=cb,
                           options={'maxiter': maxiter, 'ftol': 1e-16,
                                    'gtol': 1e-14})
            try_candidate(expand(res.x * res.x))
        except StopIteration:
            pass
        except Exception:
            pass

    # Phase 1: sharpen native best (full).
    optimize_at(state['best'], 4000, False, 0.0)
    print("phase1 R =", state['best_R'], "N =", state['best'].size)

    # Phase 1b: symmetric polish. Autoconvolution problems have symmetric optima;
    # restricting to the symmetric subspace halves the search dimension and
    # removes the flat direction, which lets L-BFGS make finer progress.
    if time.process_time() < deadline:
        hsym = 0.5 * (state['best'] + state['best'][::-1])
        try_candidate(hsym)
        if time.process_time() < deadline:
            optimize_symmetric(state['best'], 2000)
        print("phase1b sym R =", state['best_R'])

    # Phase 2: softmax ladder for the plateau, then symmetric + full polish.
    taus = [3e-3, 1e-3, 3e-4, 1e-4, 5e-5, 2e-5, 1e-5, 5e-6, 2e-6, 1e-6, 5e-7]
    for tf in taus:
        if time.process_time() >= deadline:
            break
        cc = np.convolve(state['best'], state['best'])
        peak = cc.max()
        optimize_at(state['best'], 600, True, peak * tf)
        if time.process_time() >= deadline:
            break
        optimize_symmetric(state['best'], 800)
        if time.process_time() >= deadline:
            break
        optimize_at(state['best'], 1000, False, 0.0)
        print("tau", tf, "R =", state['best_R'])
    print("phase2 R =", state['best_R'])

    # Phase 3: size variations, resample + symmetric + full.
    baseN = state['best'].size
    for d in [1, -1, 2, -2, 3, -3, 5, -5]:
        if time.process_time() >= deadline:
            break
        n = baseN + d
        if 50 <= n <= 50000:
            h_up = _resample(state['best'], n)
            if try_candidate(h_up):
                optimize_symmetric(state['best'], 1500)
                if time.process_time() >= deadline:
                    break
                optimize_at(state['best'], 1500, False, 0.0)
    print("phase3 R =", state['best_R'], "N =", state['best'].size)

    # Phase 4: alternate symmetric + full polish until deadline.
    while time.process_time() < deadline:
        before = state['best_R']
        optimize_symmetric(state['best'], 3000)
        if time.process_time() >= deadline:
            break
        optimize_at(state['best'], 3000, False, 0.0)
        if state['best_R'] <= before:
            break
    print("final R =", state['best_R'], "N =", state['best'].size)
    return state['best']

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def compute_R(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    den = s * s * np.max(L)
    if den <= 0:
        return -1.0
    return num / den


def _R_from_c(c, s):
    L = np.concatenate(([0.0], c, [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    M = np.max(L)
    den = s * s * M
    if den <= 0:
        return -1.0
    return num / den


def _corr(a, h):
    n = h.size
    full = fftconvolve(a, h[::-1], mode='full')
    return full[n-1:n-1+n]


def _grad_common(h, weight_fn):
    n = h.size
    s = h.sum()
    c = fftconvolve(h, h, mode='full')
    L = np.concatenate(([0.0], c, [0.0]))
    dA_dL = (np.concatenate(([0.0], L[:-1])) + 4.0*L
             + np.concatenate((L[1:], [0.0]))) / 3.0
    dA_dc = dA_dL[1:1+c.size]
    dA_dh = 2.0 * _corr(dA_dc, h)
    A = np.sum(L[:-1]**2 + L[:-1]*L[1:] + L[1:]**2) / 3.0
    Ms, dMs_dL = weight_fn(L, c)
    dMs_dc = dMs_dL[1:1+c.size]
    dMs_dh = 2.0 * _corr(dMs_dc, h)
    B = s * s
    R = A / (B * Ms)
    dB_dh = 2.0 * s
    dR_dh = (dA_dh/(B*Ms) - A/(B*B*Ms)*dB_dh - A/(B*Ms*Ms)*dMs_dh)
    return R, dR_dh


def _R_grad(h):
    def wf(L, c):
        M = np.max(L)
        tol = 1e-12 * max(M, 1e-300)
        mask = (L >= M - tol).astype(float)
        s = mask.sum()
        if s > 0:
            mask = mask / s
        return M, mask
    return _grad_common(h, wf)


def _smooth_R_grad(h, tau):
    def wf(L, c):
        Lmax = np.max(L)
        w = np.exp((L - Lmax) / tau)
        w /= w.sum()
        Ms = np.sum(w * L)
        dMs_dL = w * (L - Ms) / tau + w
        return Ms, dMs_dL
    return _grad_common(h, wf)


def _resample(h, N):
    if h.size == N:
        return h.copy()
    if N > h.size:
        x_old = np.linspace(0.0, 1.0, h.size)
        x_new = np.linspace(0.0, 1.0, N)
        return np.maximum(0.0, np.interp(x_new, x_old, h))
    out = np.empty(N)
    edges = np.linspace(0, h.size, N + 1)
    for i in range(N):
        a = int(np.floor(edges[i]))
        b = int(np.ceil(edges[i + 1]))
        b = max(b, a + 1)
        out[i] = h[a:b].mean()
    return np.maximum(0.0, out)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 4.0)

    if start is not None:
        base = np.asarray(start, dtype=float).ravel().copy()
        if base.size == 0 or not np.all(np.isfinite(base)) or np.any(base < 0) \
                or base.sum() <= 0:
            base = np.ones(50)
    else:
        base = np.ones(50)

    state = {'best': base.copy(), 'best_R': compute_R(base)}

    def try_candidate(h):
        h = np.asarray(h, dtype=float)
        if h.size == 0 or h.size > 50000:
            return False
        if not np.all(np.isfinite(h)) or np.any(h < 0) or h.sum() <= 0:
            return False
        r = compute_R(h)
        if r > state['best_R']:
            state['best_R'] = r
            state['best'] = h.copy()
            return True
        return False

    def optimize_at(h_start, maxiter, use_smooth, tau):
        def fun(u):
            h = u * u
            if h.sum() <= 0:
                return 1.0, np.zeros_like(u)
